package com.ahdre.pip;
import android.content.SharedPreferences;
import org.json.*;
public class Profile {
 public int size=1,speed=1,activity=1,mode=0,accessory=0,reminderMinutes=45;public boolean homeVisible=true;public double petX=.9,petY=.9,homeX=.85,homeY=1;
 public JSONObject json() throws JSONException {JSONObject j=new JSONObject();j.put("format","pip-settings");j.put("schemaVersion",1);j.put("size",size);j.put("speed",speed);j.put("activity",activity);j.put("mode",mode);j.put("accessory",accessory);j.put("reminderMinutes",reminderMinutes);j.put("homeVisible",homeVisible);j.put("petX",petX);j.put("petY",petY);j.put("homeX",homeX);j.put("homeY",homeY);return j;}
 static int integer(JSONObject j,String name,int max)throws JSONException{Object value=j.get(name);if(!(value instanceof Number))throw new JSONException("Invalid number");double d=((Number)value).doubleValue();int n=((Number)value).intValue();if(d!=n||n<0||n>max)throw new JSONException("Invalid range");return n;}
 static double fraction(JSONObject j,String key)throws JSONException{double d=j.getDouble(key);if(Double.isNaN(d)||Double.isInfinite(d)||d<0||d>1)throw new JSONException("Invalid position");return d;}
 public static Profile parse(String text)throws JSONException{if(text.length()>65536)throw new JSONException("Too large");JSONObject j=new JSONObject(text);if(!j.getString("format").equals("pip-settings")||integer(j,"schemaVersion",1)!=1)throw new JSONException("Unsupported format");Profile p=new Profile();p.size=integer(j,"size",2);p.speed=integer(j,"speed",2);p.activity=integer(j,"activity",2);p.mode=integer(j,"mode",2);p.accessory=integer(j,"accessory",5);p.reminderMinutes=integer(j,"reminderMinutes",240);if(!(j.get("homeVisible") instanceof Boolean))throw new JSONException("Invalid switch");p.homeVisible=j.getBoolean("homeVisible");p.petX=fraction(j,"petX");p.petY=fraction(j,"petY");p.homeX=fraction(j,"homeX");p.homeY=fraction(j,"homeY");return p;}
 static int nearest(int value,int[] values){int best=0;for(int i=1;i<values.length;i++)if(Math.abs(value-values[i])<Math.abs(value-values[best]))best=i;return best;}
 public static Profile from(SharedPreferences prefs){Profile p=new Profile();p.size=nearest(prefs.getInt("size",104),new int[]{80,104,136});p.speed=nearest(prefs.getInt("speed",28),new int[]{14,28,52});p.activity=prefs.getInt("activity",1);p.mode=prefs.getInt("mode",0);p.accessory=prefs.getInt("accessory",0);p.reminderMinutes=prefs.getInt("reminderMinutes",45);p.homeVisible=prefs.getBoolean("homeVisible",true);p.petX=prefs.getFloat("posX",.9f);p.petY=prefs.getFloat("posY",.9f);p.homeX=prefs.getFloat("homeX",.85f);p.homeY=prefs.getFloat("homeY",1);return p;}
 public void apply(SharedPreferences prefs){prefs.edit().putInt("size",new int[]{80,104,136}[size]).putInt("speed",new int[]{14,28,52}[speed]).putInt("activity",activity).putInt("mode",mode).putInt("accessory",accessory).putInt("reminderMinutes",reminderMinutes).putBoolean("homeVisible",homeVisible).putFloat("posX",(float)petX).putFloat("posY",(float)petY).putFloat("homeX",(float)homeX).putFloat("homeY",(float)homeY).apply();}
}
